        }

        Double pesoTotal = calcularPesoTotal(request.getItens());
        ModalidadeEntrega modalidade = ModalidadeEntrega.valueOf(request.getModalidadeEntrega());
        if (pesoTotal > modalidade.getPesoMaximoKg()) {
