        assertEquals(new BigDecimal("-20.49"), response.getAjustePagamento());
        assertEquals(new BigDecimal("425.77"), response.getTotalFinal());
        assertEquals(Integer.valueOf(1), response.getParcelas());
        assertEquals(new BigDecimal("425.77"), response.getValorParcela());
    }

