        return totalFinal;
    }

    if (forma == FormaPagamento.CARTAO && parcelas > 3) {
        return calcularParcelaComJuros(totalFinal, parcelas);
    } else {
        BigDecimal parcela = totalFinal.divide(BigDecimal.valueOf(parcelas), 10, java.math.RoundingMode.HALF_EVEN);
