        });
    }

    @Test
    public void testMotoboySobrepesoIndisponivel() {
        CheckoutRequest request = new CheckoutRequest();
        request.setItens(Arrays.asList(
            new ItemRequest("Produto Pesado", 100.0, 10, 1.0)
        ));
        request.setModalidadeEntrega("MOTOBOY");
